/* Little Things: the hundred little things in Popo's jar.
   Each: id, tier (1 = gentle starter, the small jar; 2 = the middle jar adds these; 3 = the big jar has everything),
   go (a Nearby place key that suits it, or ""), note (the paper that goes in the jar: what you did),
   popo (how she asks: Hong Kong English / broken Mandarin / her own Cantonese / broken Spanish / her own fluent Catalan),
   and sometimes a friend who chimes in [who, lines]: mei (witty, phones), wei (gentle), cats / mantou (actions only).
   Language order everywhere: en, zh, zh-Hant, es, ca. */
(function () {
var L = window.LT_THINGS = [];
function X(id, tier, go, note, popo, chime) { L.push({ id: id, t: tier, go: go, n: note, p: popo, c: chime || null }); }

/* ---------- 1 · Phones, mornings and nights ---------- */
X("a01", 1, "", ["Phone slept in the kitchen", "手机在厨房过夜", "手機在廚房過夜", "El móvil durmió en la cocina", "El mòbil va dormir a la cuina"],
 ["Tonight phone sleeps in kitchen. Not in your bed ah! Bed is for people. And maybe one cat.", "今晚手机睡厨房。不要放你床上！床是给人睡的。最多加一只猫。", "今晚部電話瞓廚房。唔准瞓你張床！張床係人瞓㗎，最多加隻貓。", "Esta noche móvil duerme en cocina. ¡No en tu cama! Cama es para personas. Y quizás un gato.", "Aquesta nit el mòbil dorm a la cuina. Al teu llit, no! El llit és per a les persones. I, com a molt, per a un gat."],
 ["cats", ["*Miso curls up on your pillow, right where the phone used to sleep*", "*味噌在你的枕头上蜷成一团，正好是手机以前睡的地方*", "*味噌在你的枕頭上蜷成一團，正好是手機以前睡的地方*", "*Miso se enrosca en tu almohada, justo donde dormía el móvil*", "*Miso s'arrauleix al teu coixí, just on dormia el mòbil*"]]);
X("a02", 2, "", ["Woke up to a real alarm clock", "被真闹钟叫醒", "被真鬧鐘叫醒", "Me despertó un despertador de verdad", "Em va despertar un despertador de debò"],
 ["Buy alarm clock lah. Tick-tock, ring-ring. Josep fix many. It wake you up, it don't show you news.", "买个闹钟啦。滴答滴答，铃铃铃。Josep 以前修过好多。它叫你起床，不给你看新闻。", "買個鬧鐘啦。滴答滴答，鈴鈴鈴。Josep 以前整過好多。佢叫醒你，又唔會塞新聞俾你睇。", "Compra despertador. Tic-tac, rin-rin. Josep arreglaba muchos. Te despierta, no te enseña noticias.", "Compra't un despertador. Tic-tac, ring-ring. En Josep n'arreglava molts. Et desperta i no t'ensenya les notícies."],
 ["wei", ["Avi Josep would have taken it apart first. Just to see.", "外公 Josep 一定会先把它拆开看看。就为了看看。", "外公 Josep 一定會先把它拆開看看。就為了看看。", "El avi Josep lo habría desmontado primero. Solo para ver.", "L'avi Josep primer l'hauria desmuntat. Només per veure com era."]]);
X("a03", 1, "", ["Morning tea by the window", "窗边喝早茶", "窗邊喝早茶", "Té de la mañana junto a la ventana", "Te del matí a la finestra"],
 ["Morning, first thing: tea, window, look outside. Phone can wait. Phone always can wait one.", "早上第一件事：茶，窗口，看看外面。手机等一下。手机永远等得了。", "朝早第一件事：沖杯茶，坐埋窗邊，望下出面。部電話等陣先，佢實等得㗎。", "Mañana, primera cosa: té, ventana, mirar fuera. Móvil puede esperar. Móvil siempre puede esperar.", "Al matí, el primer de tot: un te, la finestra i mirar fora. El mòbil pot esperar. El mòbil sempre pot esperar."]);
X("a04", 2, "", ["Made the screen grey for a day", "让屏幕灰了一天", "讓螢幕灰了一天", "Puse la pantalla en gris un día", "Vaig posar la pantalla en gris un dia"],
 ["Make phone grey. Black and white, like my old photos. Boring! Good lor. Boring phone, you put it down.", "把手机变灰色。黑白的，像我的旧照片。好闷！好。手机闷，你就放下咯。", "將部電話較做灰色。黑白嘅，好似我啲舊相噉。悶到死！好呀。部機悶，你咪放低佢囉。", "Pon móvil gris. Blanco y negro, como mis fotos viejas. ¡Aburrido! Bien. Móvil aburrido, lo dejas.", "Posa el mòbil en gris. En blanc i negre, com les meves fotos velles. Que avorrit! Doncs millor: un mòbil avorrit el deixes estar."],
 ["mei", ["Grey mode. My feed looks like a 1940s documentary. Weirdly calming. Don't tell her.", "灰色模式。我的首页像四十年代的纪录片。莫名治愈。别告诉她。", "灰階模式。我的動態像四〇年代的紀錄片。莫名療癒。別跟她說。", "Modo gris. Mi feed parece un documental de los años cuarenta. Raramente relajante. No se lo digas.", "Mode gris. El meu feed sembla un documental dels anys quaranta. Estranyament relaxant. No li ho diguis."]]);
X("a05", 1, "", ["A walk without the phone", "不带手机散步", "不帶手機散步", "Un paseo sin el móvil", "Un passeig sense el mòbil"],
 ["Go walk. Phone stays home. You get lost? Good. You ask somebody. Very nice wor.", "去走走。手机留在家。迷路？好呀。问人嘛。好好的。", "出去行下。部電話留喺屋企。蕩失路？好呀，問人囉，幾好吖。", "Ve caminar. Móvil queda en casa. ¿Te pierdes? Bien. Preguntas a alguien. Muy bonito.", "Surt a caminar. El mòbil es queda a casa. Que et perds? Millor: preguntes a algú. Que bonic."],
 ["mantou", ["*Mantou is already at the door, lead in his mouth, tail going*", "*馒头已经叼着牵引绳等在门口，尾巴摇个不停*", "*饅頭已經叼著牽繩等在門口，尾巴搖個不停*", "*Mantou ya está en la puerta, con la correa en la boca y la cola a mil*", "*Mantou ja és a la porta, amb la corretja a la boca i la cua bellugant*"]]);
X("a06", 2, "", ["Only people can ping me now", "只有人能叫我了", "只有人能叫我了", "Ahora solo me avisan personas", "Ara només m'avisen persones"],
 ["Phone go beep beep for shop, for game, for nonsense. No! Only beep for people. Turn off the rest lah.", "手机为商店响，为游戏响，为乱七八糟响。不行！只为人响。其他全关掉。", "部電話乜都響：舖頭又響，遊戲又響，亂七八糟。唔得！淨係人搵你先好響，其他全部熄咗佢。", "Móvil hace bip bip por tienda, por juego, por tonterías. ¡No! Solo bip por personas. Apaga lo demás.", "El mòbil fa pip-pip per les botigues, pels jocs, per qualsevol bestiesa. No! Només per les persones. La resta, apaga-ho."],
 ["mei", ["I turned off everything except my mum and the group chat. The group chat stays. I have limits.", "我把除了我妈和群聊之外的都关了。群聊得留着。我也是有底线的。", "我把除了我媽和群組之外的都關了。群組得留著。我也是有底線的。", "Apagué todo menos a mi madre y el grupo. El grupo se queda. Tengo límites.", "Ho he apagat tot menys la mare i el grup. El grup es queda. Tinc límits."]]);
X("a07", 3, "", ["Took the social apps off my phone", "从手机删了社交软件", "從手機刪了社群軟體", "Quité las redes sociales del móvil", "Vaig treure les xarxes socials del mòbil"],
 ["Those apps with little faces, delete from phone. Want to see friend? Go see friend lah. Face is better in person.", "那些有小脸的软件，删掉。想见朋友？去见朋友啦。脸，当面看才好。", "嗰啲社交 app，喺部電話度刪咗佢。想見朋友？就去見佢囉。個樣當面睇靚啲㗎。", "Esas aplicaciones con caritas, borra del móvil. ¿Quieres ver amigo? Ve ver amigo. Cara es mejor en persona.", "Aquestes aplicacions plenes de cares, esborra-les del mòbil. Vols veure un amic? Doncs vés a veure'l. Les cares, millor en persona."],
 ["mei", ["Fine. FINE. I'll still check from the laptop. But slower. Like a pilgrim.", "行。行吧。我还会用电脑看。但是慢一点。像朝圣。", "好啦。好啦好啦。我還是會用電腦看。但是慢一點。像朝聖。", "Vale. VALE. Lo miraré desde el portátil. Pero más lento. Como una peregrina.", "Vale. VALE. Ho miraré des de l'ordinador. Però més a poc a poc. Com una pelegrina."]]);
X("a08", 3, "", ["Answered email to a kitchen timer", "用厨房计时器回邮件", "用廚房計時器回郵件", "Contesté correos con temporizador de cocina", "Vaig contestar correus amb el rellotge de cuina"],
 ["Email: twenty minutes. I put egg timer, ding! Finish. Like dumplings, you don't cook forever one.", "邮件：二十分钟。我放个煮蛋钟，叮！完。像饺子，不能一直煮的。", "覆電郵：廿分鐘。我幫你校個煮蛋鐘，叮！收工。好似煮餃子噉，唔會煲到天光㗎嘛。", "Correo: veinte minutos. Pongo temporizador de huevo, ¡ding! Terminado. Como dumplings, no cocinas para siempre.", "Correus: vint minuts. Hi poso el rellotge dels ous i, ding!, s'ha acabat. Com els dumplings: no els bulls tota la vida."]);
X("a09", 1, "", ["Phone in a drawer for a while", "手机在抽屉里待了一会儿", "手機在抽屜裡待了一會兒", "El móvil un rato en un cajón", "El mòbil una estona al calaix"],
 ["Put phone in drawer. Close drawer. There. Now got two hands again.", "手机放进抽屉。关上。好咯。现在你又有两只手啦。", "將部電話擺入櫃桶，閂埋佢。得喇。而家你又有返兩隻手喇。", "Pon móvil en cajón. Cierra cajón. Ya. Ahora tienes dos manos otra vez.", "Posa el mòbil al calaix. Tanca el calaix. Ja està. Ara tornes a tenir dues mans."],
 ["cats", ["*Yuzu sits on the drawer. Nobody is opening it now.*", "*柚子坐在抽屉上。现在谁也打不开了。*", "*柚子坐在抽屜上。現在誰也打不開了。*", "*Yuzu se sienta encima del cajón. Ahora nadie lo abre.*", "*Yuzu s'asseu damunt del calaix. Ara ningú no l'obrirà.*"]]);
X("a10", 1, "", ["No phone in the bathroom", "厕所不带手机", "廁所不帶手機", "Sin móvil en el baño", "Sense mòbil al lavabo"],
 ["Bathroom is for bathroom. Not for phone ah! You sit, you think. Old people do this, we are fine.", "厕所是厕所。不是给手机的！你坐，你想想。老人家都这样，我们都好好的。", "廁所就係廁所，唔係玩電話嘅地方！坐喺度，諗下嘢。我哋上一代都係噉，都冇事。", "Baño es para baño. ¡No para móvil! Te sientas, piensas. Viejos hacemos esto, estamos bien.", "El lavabo és per al que és. No per al mòbil! Seus i penses. La gent gran ho fèiem així, i aquí ens tens."],
 ["mei", ["This one hurts. Personally.", "这条伤到我了。很私人地伤到。", "這條傷到我了。很私人地傷到。", "Esta duele. Personalmente.", "Aquesta fa mal. Personalment."]]);
X("a11", 2, "", ["Dressed and ate before the news", "先穿衣吃饭，再看新闻", "先穿衣吃飯，再看新聞", "Me vestí y desayuné antes de las noticias", "Em vaig vestir i esmorzar abans de les notícies"],
 ["First clothes. Then breakfast. Then news. The world is still there after toast, I promise.", "先穿衣服。再吃早餐。然后才看新闻。吐司吃完，世界还在的，我保证。", "先著衫，再食早餐，跟住先睇新聞。食完多士個世界都仲喺度，我保證。", "Primero ropa. Luego desayuno. Luego noticias. El mundo sigue ahí después de tostada, te prometo.", "Primer, vestir-se. Després, esmorzar. I després les notícies. Després de la torrada el món encara hi serà, t'ho prometo."]);
X("a12", 3, "", ["Phone docked by the door after eight", "八点后手机放门口", "八點後手機放門口", "Móvil en la entrada después de las ocho", "Mòbil a l'entrada després de les vuit"],
 ["After eight at night, phone stays by door. Like shoes. You wear shoes in bed meh?", "晚上八点以后，手机放门口。像鞋子一样。你不会穿着鞋睡觉嘛？", "夜晚八點之後，部電話放喺門口，好似對鞋噉。你唔會著鞋瞓覺㗎嘛？", "Después de ocho de noche, móvil queda en puerta. Como zapatos. ¿No duermes con zapatos, no?", "Després de les vuit del vespre, el mòbil es queda a l'entrada. Com les sabates. Que no dorms amb sabates, oi?"]);
X("a13", 1, "", ["Unsubscribed from three lists", "退订了三个邮件列表", "退訂了三個郵件清單", "Me di de baja de tres listas", "Em vaig donar de baixa de tres llistes"],
 ["Three shops send you letter every day. Three! Even my sister don't write so much. Unsubscribe lah.", "三家店天天给你写信。三家！我妹妹都没写那么多。退订啦。", "三間舖頭日日寫信俾你。三間呀！我細妹都冇寫得咁勤。退訂佢！", "Tres tiendas te mandan carta cada día. ¡Tres! Ni mi hermana escribe tanto. Date de baja.", "Tres botigues t'escriuen cada dia. Tres! Ni la meva germana escriu tant. Dona-te'n de baixa."]);
X("a14", 2, "", ["Do Not Disturb, and nobody did", "开了勿扰，真没人扰", "開了勿擾，真沒人擾", "No molestar, y nadie molestó", "No molestar, i ningú no va molestar"],
 ["Put the little moon on phone. Do not disturb. Like sign on my shop door: closed, come back tomorrow.", "开手机的小月亮。勿扰。像我店门口的牌子：关门了，明天再来。", "開咗部電話個小月亮佢，請勿打擾。好似我間舖門口塊牌：休息，聽日請早。", "Pon la lunita en móvil. No molestar. Como cartel de mi tienda: cerrado, vuelve mañana.", "Posa la lluneta al mòbil. No molestar. Com el rètol de la porta de la botiga: tancat, torneu demà."]);
X("a15", 3, "", ["Left the charger at home", "出门没带充电器", "出門沒帶充電器", "Me dejé el cargador en casa", "Em vaig deixar el carregador a casa"],
 ["Go out, leave charger. Battery go down, down. Then you look up. Sky got full battery always.", "出门，不带充电器。电池少一点，再少一点。然后你就抬头。天空永远满电的。", "出街唔好帶叉電器。啲電一路落，一路落，你就會擡頭望。個天永遠都係滿電㗎。", "Sal, deja cargador. Batería baja, baja. Luego miras arriba. El cielo siempre tiene batería llena.", "Surt i deixa't el carregador. La bateria baixa, baixa. Llavors mires amunt: el cel sempre té la bateria plena."],
 ["mei", ["Phone at 9%. I talked to a stranger on the subway. She had a dog. Ten out of ten.", "手机剩 9%。我在地铁上跟陌生人聊天了。她有条狗。满分。", "手機剩 9%。我在捷運上跟陌生人聊天了。她有隻狗。滿分。", "Móvil al 9%. Hablé con una desconocida en el metro. Tenía un perro. Diez de diez.", "Mòbil al 9%. Vaig parlar amb una desconeguda al metro. Tenia un gos. Deu sobre deu."]]);
X("a16", 3, "", ["Typed my passcode by hand", "手动输入密码解锁", "手動輸入密碼解鎖", "Escribí el código a mano", "Vaig escriure el codi a mà"],
 ["No more face opens phone. You type number. Slow! Good. Every time you think: I really need meh?", "不要再用脸开手机。你按数字。慢！好。每次你想想：我真的要吗？", "唔好再用個樣開部機，自己㩒密碼。慢？係呀，就係要慢。每次都諗下：我真係要用咩？", "No más cara abre móvil. Escribes número. ¡Lento! Bien. Cada vez piensas: ¿de verdad necesito?", "Prou de desbloquejar amb la cara. Escriu el número. És lent? Doncs millor. Cada vegada et preguntes: de debò el necessito?"]);
X("a17", 1, "books", ["Ten pages in bed", "睡前在床上读十页", "睡前在床上讀十頁", "Diez páginas en la cama", "Deu pàgines al llit"],
 ["In bed, a book. Paper one! Ten pages. You fall asleep at page six? Also fine lor.", "床上，一本书。纸的！十页。看到第六页睡着了？也行。", "瞓覺前喺床度睇本書，紙嗰隻呀！睇十頁。睇到第六頁就瞓著咗？都得嘅。", "En cama, un libro. ¡De papel! Diez páginas. ¿Te duermes en página seis? También bien.", "Al llit, un llibre. De paper! Deu pàgines. Que t'adorms a la sisena? També està bé."],
 ["wei", ["If you've nothing by the bed, there's a whole house of books in Borrowed Pages.", "床边没书的话，“借来的书”有一整栋楼的书。", "床邊沒書的話，「借來的書」有一整棟樓的書。", "Si no tienes nada en la mesilla, Páginas Prestadas es una casa entera de libros.", "Si no tens res a la tauleta, Pàgines Manllevades és una casa sencera de llibres."]]);
X("a18", 3, "", ["TV on for one named show, then off", "只为一个节目开电视，看完就关", "只為一個節目開電視，看完就關", "Tele para un programa concreto, y apagada", "Tele per a un programa concret, i apagada"],
 ["TV: you say name of show first. One show. Finish, off. Not \"I just see what is on\". Nothing on lah. Never.", "电视：先说节目名字。一个节目。看完，关。不要“我看看有什么”。什么都没有。从来都没有。", "睇電視：先講出你想睇邊個節目。一個咋，睇完就熄。唔好「睇下有咩睇」，從來都冇嘢好睇㗎。", "Tele: primero dices nombre del programa. Un programa. Termina, apagas. No \"miro qué hay\". No hay nada. Nunca.", "Tele: primer dius el nom del programa. Un de sol. S'acaba i l'apagues. Res de \"a veure què fan\". No fan mai res."]);
X("a19", 2, "", ["A quiet ride, no earphones", "一路安静，没戴耳机", "一路安靜，沒戴耳機", "Un trayecto en silencio, sin auriculares", "Un trajecte en silenci, sense auriculars"],
 ["On the bus, no earphones, no phone. Just look. Listen. You hear people talk, so funny wor. Free theatre!", "坐巴士，不戴耳机，不看手机。就看。就听。听别人说话，好好笑。免费看戏！", "搭巴士唔好戴耳筒，唔好睇電話，望下聽下。啲人傾偈好好笑㗎，免費睇戲！", "En autobús, sin auriculares, sin móvil. Solo mira. Escucha. Oyes gente hablar, muy gracioso. ¡Teatro gratis!", "A l'autobús, sense auriculars ni mòbil. Només mira i escolta. Sents la gent parlar, que divertit. Teatre de franc!"]);
X("a20", 1, "", ["Waited in a queue with my hands free", "排队时两手空空", "排隊時兩手空空", "Hice cola con las manos libres", "Vaig fer cua amb les mans lliures"],
 ["In the queue, no phone. Hands out. Look around. Maybe the lady behind you has nice hat. Tell her.", "排队，不看手机。手拿出来。看看周围。可能后面那个阿姨的帽子好靓。告诉她。", "排隊唔好睇電話，隻手攞出嚟，望下周圍。可能後面個阿姐頂帽好靚，話俾佢知啦。", "En la cola, sin móvil. Manos fuera. Mira alrededor. Quizás señora detrás tiene sombrero bonito. Dile.", "A la cua, res de mòbil. Les mans fora de les butxaques i mira al voltant. Potser la senyora del darrere porta un barret bonic: digues-l'hi."]);
X("a21", 3, "", ["Logged out when I was done", "用完就退出登录", "用完就登出", "Cerré la sesión al terminar", "Vaig tancar la sessió en acabar"],
 ["When you finish, log out. Like close the door when you leave. You don't leave door open for whole city!", "用完就退出。像出门要关门。你不会开着门让整个城市进来吧！", "用完就登出，好似出門閂門噉。你唔會打開度門俾成個城嘅人入嚟㗎嘛！", "Cuando terminas, sales. Como cerrar puerta cuando vas. ¡No dejas puerta abierta para toda la ciudad!", "Quan acabis, tanca la sessió. Com tancar la porta quan surts. No deixaries la porta oberta a tota la ciutat!"]);
X("a22", 2, "", ["A bare home screen", "清空了主屏幕", "清空了主畫面", "Una pantalla de inicio vacía", "Una pantalla d'inici buida"],
 ["Home screen so busy ah! Like my kitchen at New Year. Take everything off. Only phone, map, camera. Clean.", "主屏幕这么乱！像我过年的厨房。全部拿走。只要电话，地图，相机。干干净净。", "個主畫面亂到好似我過年嘅廚房噉！全部拎走佢，淨係留電話、地圖、相機。乾乾淨淨。", "¡Pantalla de inicio tan llena! Como mi cocina en Año Nuevo. Quita todo. Solo teléfono, mapa, cámara. Limpio.", "La pantalla d'inici és plena com la meva cuina per Cap d'Any. Treu-ho tot. Només el telèfon, el mapa i la càmera. Net."]);
X("a23", 2, "", ["Switched autoplay off", "关掉了自动播放", "關掉了自動播放", "Desactivé la reproducción automática", "Vaig desactivar la reproducció automàtica"],
 ["Video finish, next video start by itself. Who ask? Nobody ask! Turn it off. You choose. Not the machine.", "视频完了，下一个自己开始。谁要？冇人要！关掉。你来选。不是机器选。", "一條片睇完，下一條自己又播。邊個叫佢播？冇人叫呀！熄咗佢。你揀，唔係部機揀。", "Video termina, otro video empieza solo. ¿Quién pide? ¡Nadie pide! Apágalo. Tú eliges. No la máquina.", "S'acaba un vídeo i el següent comença tot sol. Qui li ho ha demanat? Ningú! Apaga-ho. Tries tu, no la màquina."]);
X("a24", 3, "", ["Wrote my question on paper first", "先把要搜的写在纸上", "先把要搜的寫在紙上", "Escribí la pregunta en papel antes", "Vaig escriure la pregunta en paper abans"],
 ["Before you search, write question on paper. Half the time you know the answer already. Other half, you forget. Fine lor!", "搜之前，问题先写在纸上。一半时候你已经知道答案。另一半，你忘了。都好！", "搜嘢之前，先將個問題寫喺張紙度。一半時間你自己已經知答案，另一半你會唔記得咗。都好！", "Antes de buscar, escribe pregunta en papel. Mitad de veces ya sabes respuesta. Otra mitad, olvidas. ¡Bien!", "Abans de buscar, escriu la pregunta en un paper. La meitat de les vegades ja saps la resposta. L'altra meitat te n'oblides. Perfecte!"]);
X("a25", 3, "cabin", ["A whole day without screens", "一整天不碰屏幕", "一整天不碰螢幕", "Un día entero sin pantallas", "Un dia sencer sense pantalles"],
 ["One whole day, no screen. Sunday is good. Cook, walk, sleep in afternoon. Like before. Before not so bad one.", "一整天，没有屏幕。礼拜天最好。做饭，逛街，下午睡觉。像以前那样。以前也不差的。", "成日唔掂任何螢幕。揀星期日最好：煮飯、行街、晏晝瞓個覺。好似以前噉，以前都唔差㗎。", "Un día entero, sin pantalla. Domingo es bueno. Cocinar, caminar, dormir en tarde. Como antes. Antes no era tan malo.", "Un dia sencer sense pantalles. El diumenge va bé: cuinar, passejar, fer la migdiada. Com abans. Abans no estava tan malament."],
 ["mei", ["I tried. By 4 p.m. I had alphabetised her spice rack. She was thrilled. I was concerned.", "我试了。下午四点我已经把她的调料按字母排好了。她超开心。我有点担心自己。", "我試了。下午四點我已經把她的調味料按字母排好了。她超開心。我有點擔心自己。", "Lo intenté. A las cuatro ya había ordenado sus especias por orden alfabético. Ella, feliz. Yo, preocupada.", "Ho vaig provar. A les quatre ja li havia ordenat les espècies per ordre alfabètic. Ella, encantada. Jo, preocupada."]]);

/* ---------- 2 · Paper, hands and things you can hold ---------- */
X("b01", 2, "", ["Wrote in a paper notebook", "在纸本子上写了字", "在紙本子上寫了字", "Escribí en un cuaderno de papel", "Vaig escriure en una llibreta de paper"],
 ["Get small notebook, paper. Write what you think. Bad handwriting is OK. Mine very terrible one, Josep read anyway.", "买个小本子，纸的。写你想的事。字丑冇关系。我的字好丑，Josep 也照样看。", "買本細細本嘅簿仔，寫低你諗嘅嘢。字醜唔緊要，我啲字仲醜，Josep 都照睇。", "Compra cuaderno pequeño, papel. Escribe lo que piensas. Letra fea está bien. La mía terrible, Josep leía igual.", "Compra't una llibreta petita, de paper. Escriu el que penses. La lletra lletja no fa res: la meva és horrible i en Josep la llegia igualment."]);
X("b02", 3, "", ["Wore a watch instead of checking my phone", "戴表看时间，不看手机", "戴錶看時間，不看手機", "Llevé reloj en vez de mirar el móvil", "Vaig portar rellotge en lloc de mirar el mòbil"],
 ["Wear a watch. You want time, you look at wrist. Only time! Phone, you look for time, you see fifty things.", "戴块表。想知道几点，看手腕。只有时间！看手机看时间，你看到五十样东西。", "戴隻錶啦。想知幾點，睇下手腕，淨係得時間！睇電話睇時間，你會見到五十樣嘢。", "Lleva reloj. Quieres hora, miras muñeca. ¡Solo hora! Móvil, buscas hora, ves cincuenta cosas.", "Porta rellotge. Vols saber l'hora? Mira't el canell, i només hi ha l'hora! Al mòbil busques l'hora i hi veus cinquanta coses."],
 ["wei", ["Avi's old watch still runs a minute slow a day. Popo says that's on purpose.", "外公的旧表还是每天慢一分钟。婆婆说那是故意的。", "外公的舊錶還是每天慢一分鐘。婆婆說那是故意的。", "El reloj viejo del avi sigue atrasando un minuto al día. Popo dice que es a propósito.", "El rellotge vell de l'avi encara s'endarrereix un minut cada dia. La Popo diu que és expressament."]]);
X("b03", 2, "bar", ["Wrote a recipe on a card", "把一道菜谱写在卡片上", "把一道食譜寫在卡片上", "Escribí una receta en una ficha", "Vaig escriure una recepta en una fitxa"],
 ["Write a recipe on a card lah. Your mother's, your own, anyone. With hand! Grease spots make it better.", "菜谱写在卡片上。你妈妈的，你自己的，谁的都行。用手写！有油渍更好。", "將個食譜寫喺張咭度，阿媽嘅、你自己嘅、邊個嘅都得。用手寫呀！沾到啲油仲正。", "Escribe receta en una tarjeta. De tu madre, tuya, de quien sea. ¡Con mano! Manchas de aceite la hacen mejor.", "Escriu una recepta en una fitxa. La de la teva mare, la teva, la de qui sigui. A mà! Amb taques d'oli encara és millor."],
 ["wei", ["If you'd like it kept, Popo has a recipe box at Next Door. Other people's grandmothers are in there too.", "想留着的话，婆婆在“隔壁”有个菜谱盒。里面也有别人家的外婆。", "想留著的話，婆婆在「隔壁」有個食譜盒。裡面也有別人家的外婆。", "Si quieres guardarla, Popo tiene una caja de recetas en Al Lado. Ahí están las abuelas de otros también.", "Si la vols guardar, la Popo té una capsa de receptes a Al Costat. Hi ha les àvies d'altres persones, també."]]);
X("b04", 3, "", ["Hung up a paper calendar", "挂了一本纸日历", "掛了一本紙日曆", "Colgué un calendario de papel", "Vaig penjar un calendari de paper"],
 ["Paper calendar on the wall, in kitchen. Write birthdays! Everybody see. Nobody forget Popo's birthday again, OK?", "纸日历挂墙上，在厨房。写生日！大家都看到。再也没人忘记婆婆生日。", "掛本紙月曆喺廚房，寫低晒啲人嘅生日！個個都見到，冇人會再唔記得婆婆生日。", "Calendario de papel en pared, en cocina. ¡Escribe cumpleaños! Todos ven. Nadie olvida cumpleaños de Popo otra vez.", "Un calendari de paper a la paret de la cuina. Hi escrius els aniversaris i tothom els veu. Ningú no s'oblidarà mai més del de la Popo."],
 ["mei", ["It was ONE time. I was in a different time zone. Technically I was early.", "就那一次。我在别的时区。严格来说我是提前了。", "就那一次。我在別的時區。嚴格來說我是提早了。", "Fue UNA vez. Estaba en otra zona horaria. Técnicamente llegué antes.", "Va ser UNA vegada. Estava en una altra zona horària. Tècnicament, vaig arribar abans."]]);
X("b05", 3, "", ["Read a paper newspaper on Sunday", "星期天读了纸质报纸", "星期天讀了紙本報紙", "Leí un periódico de papel el domingo", "Vaig llegir un diari de paper diumenge"],
 ["Sunday, buy newspaper. Paper one, big, noisy. Read with coffee. Then wrap fish, or clean windows. Very useful one!", "礼拜天，买份报纸。纸的，好大，沙沙响。配咖啡看。然后包鱼，或者擦窗。好有用！", "星期日買份報紙，紙嗰份呀，大大份沙沙聲。配杯嘢飲慢慢睇，睇完仲可以包魚抹窗，好有用㗎！", "Domingo, compra periódico. De papel, grande, ruidoso. Lee con café. Luego envuelves pescado, o limpias ventana. ¡Muy útil!", "Diumenge, compra el diari. De paper, gran, que fa soroll. Llegeix-lo amb un cafè. Després serveix per embolicar peix o netejar vidres. Utilíssim!"]);
X("b06", 1, "", ["One sticky note, one list", "一张便利贴，一张清单", "一張便利貼，一張清單", "Una nota adhesiva, una lista", "Un pòsit, una llista"],
 ["Today, one small paper. Write what to do. Only what fits! Not fit, not today lor.", "今天，一张小纸。写要做的事。写得下的才算！写不下，就不是今天的。", "今日淨係用一張細紙仔寫低要做嘅嘢。寫得落先算！寫唔落，就唔係今日嘅事。", "Hoy, un papel pequeño. Escribe qué hacer. ¡Solo lo que cabe! No cabe, no hoy.", "Avui, un paperet. Hi escrius el que has de fer, només el que hi càpiga. Si no hi cap, no és per avui."]);
X("b07", 3, "", ["Looked a word up in a paper dictionary", "用纸字典查了一个词", "用紙字典查了一個詞", "Busqué una palabra en un diccionario de papel", "Vaig buscar una paraula en un diccionari de paper"],
 ["Look up one word in paper dictionary. You find also the word before and after. Three words, one price!", "纸字典查一个字。前面和后面的字，你都看到。三个字，一个价钱！", "用本紙字典查一個字。你會順便見到前一個同後一個，買一送二呀！", "Busca una palabra en diccionario de papel. Encuentras también la de antes y la de después. ¡Tres palabras, un precio!", "Busca una paraula en un diccionari de paper. Hi trobaràs també la d'abans i la de després. Tres paraules pel preu d'una!"],
 ["wei", ["Popo's little dictionary still has Avi's Catalan pencilled next to every English word.", "婆婆那本小字典里，每个英文词旁边都还有外公用铅笔写的加泰罗尼亚语。", "婆婆那本小字典裡，每個英文詞旁邊都還有外公用鉛筆寫的加泰隆尼亞語。", "El diccionario pequeño de Popo aún tiene el catalán del avi a lápiz junto a cada palabra inglesa.", "El diccionari petit de la Popo encara té el català de l'avi escrit a llapis al costat de cada paraula anglesa."]]);
X("b08", 2, "jukebox", ["Listened to a whole album", "从头到尾听完一张专辑", "從頭到尾聽完一張專輯", "Escuché un disco entero", "Vaig escoltar un disc sencer"],
 ["One album, from first song to last. No jumping! The boring song in the middle, that one become your favourite wor.", "一张唱片，第一首听到最后一首。不要跳！中间那首闷的，以后会变成你最喜欢的。", "一張碟由第一首聽到最後一首，唔准跳！中間嗰首悶悶哋嘅，遲啲會變成你最鍾意嗰首。", "Un disco, de primera canción a última. ¡No saltar! La canción aburrida del medio, esa será tu favorita.", "Un disc, de la primera cançó a l'última. Sense saltar-ne cap! La cançó avorrida del mig acabarà sent la teva preferida."],
 ["mei", ["Hot take: track seven is always the real one.", "暴论：第七首永远才是真的。", "暴論：第七首永遠才是真的。", "Opinión polémica: la siete siempre es la buena.", "Opinió polèmica: la set sempre és la bona."]]);
X("b09", 3, "", ["Took photos on film", "用胶卷拍了照片", "用底片拍了照片", "Hice fotos con carrete", "Vaig fer fotos amb carret"],
 ["Film camera. Twenty-four photos only. So you choose! And you wait one week to see. Waiting is half the fun ah.", "胶卷相机。只有二十四张。所以你要挑！还要等一个礼拜才看到。等，也是一半乐趣。", "用菲林相機啦。得廿四張咋，所以要揀清楚！仲要等一個禮拜先睇到，等都係一半樂趣嚟㗎。", "Cámara de carrete. Solo veinticuatro fotos. ¡Así eliges! Y esperas una semana para ver. Esperar es la mitad de diversión.", "Càmera de carret. Només vint-i-quatre fotos, així que tries! I esperes una setmana per veure-les. Esperar és la meitat de la gràcia."],
 ["mei", ["Film is so back. I look amazing in grain.", "胶片又火了。我在颗粒感里美得不行。", "底片又紅了。我在顆粒感裡美得不行。", "El carrete ha vuelto. Salgo increíble con grano.", "El carret ha tornat. Amb gra surto increïble."]]);
X("b10", 3, "", ["Printed photos to hold", "冲印了能拿在手里的照片", "沖印了能拿在手裡的照片", "Imprimí fotos para tenerlas en la mano", "Vaig imprimir fotos per tenir-les a la mà"],
 ["Print ten photos. Real ones! Put on fridge. Phone got ten thousand, nobody see. Fridge, everybody see.", "洗十张照片。真的！贴冰箱上。手机一万张，冇人看。冰箱，人人都看。", "曬十張相出嚟，真嘅相呀！貼喺雪櫃度。部電話一萬張冇人睇，雪櫃個個都睇到。", "Imprime diez fotos. ¡De verdad! Ponlas en nevera. Móvil tiene diez mil, nadie ve. Nevera, todos ven.", "Imprimeix deu fotos. De veritat! A la nevera. Al mòbil en tens deu mil i no les veu ningú. A la nevera, tothom."],
 ["wei", ["She's got twelve in her album at No Hurry, and she knows every one by heart.", "她在“不急”的相册里有十二张，每一张她都记得。", "她在「不急」的相簿裡有十二張，每一張她都記得。", "Tiene doce en su álbum de Sin Prisa, y se sabe cada una de memoria.", "En té dotze al seu àlbum de Sense Pressa, i se les sap totes de memòria."]]);
X("b11", 3, "", ["Paid in cash for a week", "一个星期只用现金", "一個星期只用現金", "Pagué en efectivo una semana", "Vaig pagar en efectiu una setmana"],
 ["One week, only cash. You see money go out of hand, you feel it. Card, you don't feel. Card is sneaky one.", "一个礼拜，只用现金。钱从手里出去，你有感觉。卡没感觉。卡好狡猾。", "一個禮拜淨係用現金。啲錢由你手度走，你先有感覺。張卡冇感覺㗎，好蠱惑。", "Una semana, solo efectivo. Ves dinero salir de mano, lo sientes. Tarjeta, no sientes. Tarjeta es tramposa.", "Una setmana només amb efectiu. Veus com els diners et surten de la mà, i ho notes. Amb la targeta no notes res. La targeta és traïdora."]);
X("b12", 2, "", ["A board game out on the table", "桌上摆了一盘桌游", "桌上擺了一盤桌遊", "Un juego de mesa sobre la mesa", "Un joc de taula damunt la taula"],
 ["Leave a board game on the table. Open! Somebody walk by, sure they sit. Mahjong is best. Josep always lose.", "桌上放盘棋。打开的！有人走过，就坐下。麻将最好。Josep 老是输。", "擺副棋喺枱面，打開咗嘅！有人行過就會坐低。打麻雀最好，Josep 次次都輸。", "Deja juego de mesa en la mesa. ¡Abierto! Alguien pasa, se sienta. Mahjong es mejor. Josep siempre perdía.", "Deixa un joc de taula damunt la taula, obert! Algú passa i s'asseu. El mahjong és el millor. En Josep sempre perdia."],
 ["cats", ["*Yuzu knocks one piece off the table and watches it roll*", "*柚子把一颗棋子拍下桌，看着它滚远*", "*柚子把一顆棋子拍下桌，看著它滾遠*", "*Yuzu tira una ficha de la mesa y la mira rodar*", "*Yuzu tira una fitxa de la taula i la mira rodolar*"]]);
X("b13", 2, "", ["A crossword in pencil", "用铅笔做了一个填字游戏", "用鉛筆做了一個填字遊戲", "Un crucigrama a lápiz", "Uns mots encreuats a llapis"],
 ["Crossword, with pencil. Not pen, you make mistake. Everybody make mistake. Pencil knows.", "填字游戏，用铅笔。不要用钢笔，你会写错。人人都会写错。铅笔知道的。", "做填字遊戲要用鉛筆，唔好用原子筆，你會寫錯㗎嘛。個個都會錯，鉛筆最明白。", "Crucigrama, con lápiz. No bolígrafo, te equivocas. Todos se equivocan. El lápiz sabe.", "Mots encreuats, amb llapis. Amb bolígraf no, que t'equivocaràs. Tothom s'equivoca. El llapis ja ho sap."]);
X("b14", 3, "", ["Found my way with a paper map", "用纸地图找路", "用紙地圖找路", "Me orienté con un mapa de papel", "Vaig trobar el camí amb un mapa de paper"],
 ["Paper map. Big, you can't fold back right, nobody can lah. But you see whole city at once. Phone only show the little dot.", "纸地图。好大，折不回去，谁都折不回去。但是你一眼看完整个城市。手机只给你看一个小点。", "用紙地圖。大大張，摺唔返原樣，冇人摺得返㗎。但係成個城市一眼睇晒，部電話淨係俾你睇個小點。", "Mapa de papel. Grande, no puedes doblar bien, nadie puede. Pero ves toda la ciudad. Móvil solo enseña el puntito.", "Un mapa de paper. És gran i no hi ha manera de tornar-lo a plegar, ningú no en sap. Però hi veus tota la ciutat de cop. El mòbil només t'ensenya el puntet."]);
X("b15", 3, "", ["Started a paper address book", "开始记一本纸通讯录", "開始記一本紙通訊錄", "Empecé una libreta de direcciones", "Vaig començar una llibreta d'adreces"],
 ["Address book with pen. Name, street, birthday. Then you can send letter! Phone lose everything. Book never.", "用笔写通讯录。名字，街，生日。这样你就能寄信！手机会丢东西。本子不会。", "用支筆寫本地址簿：名、街、生日。噉你就寄得信喇！部電話會唔見晒啲嘢，本簿唔會。", "Libreta de direcciones con bolígrafo. Nombre, calle, cumpleaños. ¡Luego puedes mandar carta! Móvil pierde todo. Libreta nunca.", "Una llibreta d'adreces, a mà. Nom, carrer, aniversari. Així podràs enviar cartes! El mòbil ho perd tot. La llibreta, mai."]);
X("b16", 1, "", ["A grocery list on paper", "纸上写了购物清单", "紙上寫了購物清單", "La lista de la compra en papel", "La llista de la compra en paper"],
 ["Shopping list on paper. Back of envelope is good. And you write \"eggs\" ah. You always forget eggs.", "买东西的清单写纸上。信封背面就行。还要写“鸡蛋”。你老是忘记鸡蛋。", "買餸清單寫喺張紙度，信封背面都得。記得寫「雞蛋」呀，你次次都唔記得買蛋。", "Lista de compra en papel. Detrás de sobre está bien. Y escribes \"huevos\". Siempre olvidas huevos.", "La llista de la compra, en paper. El dors d'un sobre ja va bé. I escriu \"ous\", que sempre te n'oblides."],
 ["mantou", ["*Mantou watches the list very closely, hoping for \"sausages\"*", "*馒头盯着清单看，盼着上面写了“香肠”*", "*饅頭盯著清單看，盼著上面寫了「香腸」*", "*Mantou mira la lista muy atento, a ver si pone \"salchichas\"*", "*Mantou mira la llista molt atent, a veure si hi posa \"salsitxes\"*"]]);
X("b17", 2, "forest", ["Pressed a leaf into a bookmark", "压了一片叶子做书签", "壓了一片葉子做書籤", "Prensé una hoja para marcapáginas", "Vaig premsar una fulla per fer un punt de llibre"],
 ["Pick up one nice leaf. Put inside heavy book, one week. Flat! Now bookmark. Free, pretty, smell like outside.", "捡一片靓叶子。夹进厚书，一个礼拜。压平咯！现在是书签。免费，好看，有外面的味道。", "執塊靚葉，夾喺本厚書度一個禮拜，扁晒！變咗書籤喇。唔使錢，又靚，仲有陣街外嘅味。", "Recoge una hoja bonita. Pon dentro de libro pesado, una semana. ¡Plana! Ahora marcapáginas. Gratis, bonito, huele a fuera.", "Cull una fulla bonica. Posa-la dins d'un llibre gruixut una setmana. Plana! Ja tens punt de llibre. De franc, bonic, i fa olor de fora."]);
X("b18", 3, "", ["Ground the coffee by hand", "手磨了咖啡", "手磨了咖啡", "Molí el café a mano", "Vaig moldre el cafè a mà"],
 ["Grind coffee with hand. Round and round. Slow. Smell come up. I don't drink coffee, but this smell, OK lah, I like.", "用手磨咖啡。转呀转。慢慢的。香味上来了。我不喝咖啡，但是这个味道，好，我喜欢。", "用手磨咖啡，轉吓轉吓，慢慢嚟，啲香味就出嚟喇。我唔飲咖啡㗎，不過呢陣味，好啦，我鍾意。", "Muele café con mano. Vuelta y vuelta. Lento. Sube el olor. Yo no bebo café, pero este olor, vale, me gusta.", "Mol el cafè a mà. Volta i volta, a poc a poc, i puja l'olor. Jo no en bec, de cafè, però aquesta olor, mira, m'agrada."],
 ["mei", ["Forearm workout and a latte. Wellness girlies, take notes.", "又练小臂又有拿铁。养生姐妹们，记笔记。", "又練前臂又有拿鐵。養生姊妹們，筆記抄起來。", "Brazo trabajado y un latte. Chicas wellness, tomad nota.", "Avantbraç treballat i un latte. Noies del wellness, preneu nota."]]);
X("b19", 2, "", ["Did one chore slowly, on purpose", "慢慢地做了一件家务", "慢慢地做了一件家務", "Hice una tarea despacio, a propósito", "Vaig fer una feina de casa a poc a poc, expressament"],
 ["One chore, slow. Fold towels like they are for a guest. Sweep like you have all day. You do have all day!", "一样家务，慢慢做。叠毛巾，像给客人叠。扫地，像你有一整天。你真的有一整天！", "揀一樣家務慢慢做。摺毛巾好似俾人客用噉，掃地好似成日都得閒噉。你真係成日得閒㗎！", "Una tarea, lenta. Dobla toallas como para invitado. Barre como si tienes todo el día. ¡Sí tienes todo el día!", "Una feina de casa, a poc a poc. Plega les tovalloles com si fossin per a un convidat. Escombra com si tinguessis tot el dia. I el tens!"]);
X("b20", 3, "", ["Started a jar of my own", "开始做自己的回忆罐", "開始做自己的回憶罐", "Empecé un tarro mío", "Vaig començar un pot meu"],
 ["Make your own jar, at home lah. Real one, with real paper. Good day, you write, you put in. Bad day, you read.", "在家做个你自己的罐子。真的，用真的纸。好日子，写下来放进去。不好的日子，拿出来看。", "喺屋企整個你自己嘅樽，真嘅樽，真嘅紙。好日子就寫低擺入去，唔開心嗰日就攞出嚟睇。", "Haz tu propio tarro, en casa. De verdad, con papel de verdad. Día bueno, escribes, metes. Día malo, lees.", "Fes-te el teu propi pot, a casa. Un de debò, amb paper de debò. Els dies bons hi escrius i ho poses a dins. Els dies dolents, ho llegeixes."],
 ["cats", ["*Miso inspects the empty jar and decides it is a cat bed*", "*味噌检查了一下空罐子，认定它是猫窝*", "*味噌檢查了一下空罐子，認定它是貓窩*", "*Miso inspecciona el tarro vacío y decide que es una cama de gato*", "*Miso inspecciona el pot buit i decideix que és un llit per a gats*"]]);
X("b21", 2, "kintsugi", ["Sewed a button back on", "缝回了一颗扣子", "縫回了一顆釦子", "Cosí un botón", "Vaig cosir un botó"],
 ["Aiya, button fall off? Don't throw shirt! Needle, thread, five minutes. Come, I show you. Over, under, over, under, knot.", "掉了颗扣子？衣服不要扔！针，线，五分钟。来，我教你。上，下，上，下，打结。", "甩咗粒鈕？唔好掉件衫呀！針、線、五分鐘。嚟，我教你：上、落、上、落，打個結。", "¿Botón cae? ¡No tires camisa! Aguja, hilo, cinco minutos. Ven, te enseño. Arriba, abajo, arriba, abajo, nudo.", "Se t'ha descosit un botó? No llencis la camisa! Agulla, fil i cinc minuts. Vine, que t'ensenyo: amunt, avall, amunt, avall, i un nus."],
 ["cats", ["*Miso pats the thread. Then sits on it.*", "*味噌拍了拍线。然后坐在了上面。*", "*味噌拍了拍線。然後坐在了上面。*", "*Miso le da toquecitos al hilo. Luego se sienta encima.*", "*Miso dona copets al fil. Després s'hi asseu a sobre.*"]]);
X("b22", 3, "", ["Sharpened the kitchen knives", "磨了厨房的刀", "磨了廚房的刀", "Afilé los cuchillos de cocina", "Vaig esmolar els ganivets de la cuina"],
 ["Sharpen the knives. Blunt knife is dangerous, sharp knife is friend. Then you cut tomato like a chef wor.", "把刀磨一磨。钝刀危险，快刀是朋友。然后你切番茄，像大厨一样。", "磨下啲刀。鈍刀先危險，利刀係你朋友。磨完切番茄好似大廚噉。", "Afila los cuchillos. Cuchillo romo es peligroso, cuchillo afilado es amigo. Luego cortas tomate como chef.", "Esmola els ganivets. Un ganivet esmussat és perillós; un d'esmolat és un amic. Després talles el tomàquet com un xef."]);
X("b23", 3, "restaurant", ["Lit a candle when it got dark", "天黑时点了一支蜡烛", "天黑時點了一支蠟燭", "Encendí una vela al oscurecer", "Vaig encendre una espelma en fosquejar"],
 ["When it get dark, light one candle. Beeswax, smell like honey. Turn off big light. Everybody look nicer.", "天黑了，点一支蜡烛。蜂蜡的，有蜂蜜味。关大灯。大家都好看一点。", "天黑就點枝蠟燭，蜂蠟嗰種，有陣蜜糖味。熄咗盞大燈，個個都靚啲。", "Cuando oscurece, enciende una vela. Cera de abeja, huele a miel. Apaga luz grande. Todos se ven más guapos.", "Quan es fa fosc, encén una espelma. De cera d'abella, que fa olor de mel. Apaga el llum gran. Tothom fa més bona cara."]);
X("b24", 3, "", ["Wrote with a fountain pen", "用钢笔写了字", "用鋼筆寫了字", "Escribí con pluma estilográfica", "Vaig escriure amb ploma estilogràfica"],
 ["Fountain pen. Ink on your fingers, very nice one. Your handwriting slow down, your thinking slow down too.", "钢笔。手指有墨水，好好的。字写慢了，想事情也慢了。", "用鋼筆寫字，手指沾到啲墨，幾好吖。寫字慢落嚟，個腦都會慢落嚟。", "Pluma estilográfica. Tinta en tus dedos, muy bonito. Tu letra va lenta, tu pensar va lento también.", "Ploma estilogràfica. Tinta als dits, que bonic. La lletra s'alenteix, i el pensament també."]);
X("b25", 1, "", ["Washed up by hand, nothing in my ears", "手洗碗，没戴耳机", "手洗碗，沒戴耳機", "Fregué a mano, sin nada en las orejas", "Vaig rentar plats a mà, sense res a les orelles"],
 ["Wash dishes with hand, no earphones. Warm water, bubbles. You think about the dinner. Good dinner, good dishes.", "用手洗碗，不戴耳机。热水，泡泡。你想想刚才那顿饭。好饭，好碗。", "用手洗碗，唔好戴耳筒。暖水、泡泡，諗返啱啱餐飯。好飯好碗。", "Lava platos con mano, sin auriculares. Agua caliente, burbujas. Piensas en la cena. Buena cena, buenos platos.", "Renta els plats a mà, sense auriculars. Aigua calenta, bombolles. Penses en el sopar. Bon sopar, bons plats."]);

/* ---------- 3 · Air, light, the body and the weather ---------- */
X("c01", 3, "", ["Outside within ten minutes of waking", "醒来十分钟内出了门", "醒來十分鐘內出了門", "Fuera a los diez minutos de despertar", "Fora als deu minuts de despertar-me"],
 ["Wake up, go outside in ten minutes. Pyjamas OK lah, coat on top! Sky first, then everything else.", "起床，十分钟内出门。穿睡衣也行，外面穿件外套！先看看天，再做别的。", "起身十分鐘內出去一陣。著住睡衣都得，記得加件褸呀！先望天，其他嘢遲啲先。", "Despiertas, sales fuera en diez minutos. Pijama vale, ¡abrigo encima! Primero cielo, luego todo lo demás.", "Et despertes i surts a fora en deu minuts. En pijama, si cal, però amb l'abric a sobre! Primer el cel, després tota la resta."]);
X("c02", 2, "meadow", ["Barefoot on the grass", "光脚踩了草地", "光腳踩了草地", "Descalzo en la hierba", "Descalç a l'herba"],
 ["Take off shoes. Stand on grass. Cold ah? Little bit only. Feet are happy, they never go out.", "脱鞋。站在草地上。冷？一点点啦。脚好开心，它们从来不出门的。", "除咗對鞋，企喺草地度。凍？少少啫。對腳好開心㗎，佢哋平時都冇得出街。", "Quita zapatos. Ponte en hierba. ¿Frío? Un poquito. Pies están felices, nunca salen.", "Treu-te les sabates i trepitja l'herba. Fred? Una mica. Els peus estan contents: no surten mai."]);
X("c03", 3, "forest", ["Learnt the names of five trees or birds", "认识了五种树或鸟", "認識了五種樹或鳥", "Aprendí cinco árboles o pájaros", "Vaig aprendre cinc arbres o ocells"],
 ["Learn five trees, or five birds, near your house. They are your neighbours! You know their names, they know yours. Maybe lor.", "认识家附近五种树，或者五种鸟。它们是你邻居！你知道它们名字，它们也知道你的。可能吧。", "認識屋企附近五種樹，或者五種雀仔。佢哋係你街坊嚟㗎！你識佢哋個名，佢哋可能都識你。", "Aprende cinco árboles, o cinco pájaros, cerca de casa. ¡Son tus vecinos! Sabes sus nombres, saben el tuyo. Quizás.", "Aprèn cinc arbres, o cinc ocells, del teu barri. Són els teus veïns! Tu saps com es diuen, i potser ells també saben com et dius tu."],
 ["wei", ["Start with the one outside your window. Then the one it argues with.", "从你窗外那棵开始。然后是跟它吵架的那只。", "從你窗外那棵開始。然後是跟它吵架的那隻。", "Empieza por el de tu ventana. Luego, el que discute con él.", "Comença pel de davant la finestra. Després, el que s'hi baralla."]]);
X("c04", 2, "cloud", ["Watched a whole sunset", "看完了一整场日落", "看完了一整場日落", "Vi una puesta de sol entera", "Vaig veure una posta de sol sencera"],
 ["Watch sunset. Whole thing! Not one photo and go. Stay until the sky go purple. That one is the best part.", "看日落。看完！不要拍一张就走。等到天变紫色。那个才最好看。", "睇日落，要睇晒成個！唔好影張相就走，等到個天變紫色先，嗰段最靚。", "Mira la puesta de sol. ¡Entera! No una foto y te vas. Quédate hasta cielo morado. Esa es la mejor parte.", "Mira la posta de sol. Sencera! Res de fer una foto i marxar. Queda't fins que el cel es torni lila: és la millor part."],
 ["mei", ["Golden hour without posting it. Revolutionary. Unhinged. I did it once.", "黄金时刻但不发出去。革命性的。疯了。我做过一次。", "黃金時刻但不發出去。革命性的。瘋了。我做過一次。", "La hora dorada sin publicarla. Revolucionario. Una locura. Lo hice una vez.", "L'hora daurada sense penjar-la. Revolucionari. Una bogeria. Ho vaig fer una vegada."]]);
X("c05", 3, "garden", ["Herbs growing on the windowsill", "窗台上种了香草", "窗台上種了香草", "Hierbas en la ventana", "Herbes a l'ampit de la finestra"],
 ["Plant herbs on the window. Basil, mint, spring onion. You cook, you cut a little. Like got small garden in your pocket.", "窗口种香草。罗勒，薄荷，葱。做饭剪一点。像口袋里有个小花园。", "喺窗台種啲香草：九層塔、薄荷、蔥。煮飯剪少少落鑊，好似袋住個小花園噉。", "Planta hierbas en ventana. Albahaca, menta, cebolleta. Cocinas, cortas un poco. Como un jardín pequeño en tu bolsillo.", "Planta herbes a la finestra: alfàbrega, menta, ceba tendra. Quan cuines, en talles una mica. És com portar un hortet a la butxaca."]);
X("c06", 1, "", ["Opened the windows in the morning", "早上开了窗", "早上開了窗", "Abrí las ventanas por la mañana", "Vaig obrir les finestres al matí"],
 ["Open window in the morning ah! Old air out, new air in. Five minutes. Even in winter. Then close, wear jacket.", "早上开窗！旧空气出去，新空气进来。五分钟。冬天也要。然后关窗，穿外套。", "朝早打開個窗！舊空氣出，新空氣入，五分鐘就得，冬天都要。開完閂返，著返件褸。", "¡Abre ventana por la mañana! Aire viejo fuera, aire nuevo dentro. Cinco minutos. También en invierno. Luego cierra, ponte chaqueta.", "Obre la finestra al matí! Aire vell fora, aire nou dins. Cinc minuts, també a l'hivern. Després la tanques i et poses la jaqueta."]);
X("c07", 2, "", ["Looked at the moon and knew its phase", "看月亮，认出了月相", "看月亮，認出了月相", "Miré la luna y supe su fase", "Vaig mirar la lluna i en vaig saber la fase"],
 ["Look at the moon tonight. Fat or thin? Getting bigger or smaller? No app! Your eyes. In Hong Kong everybody know, for festival.", "今晚看月亮。胖还是瘦？变大还是变小？不用软件！用眼睛看。在香港，我们看月亮过节的。", "今晚望下個月亮：肥定瘦？大緊定細緊？唔准用 app，用對眼睇！我哋喺香港就係睇月亮過節㗎。", "Mira la luna esta noche. ¿Gorda o flaca? ¿Crece o mengua? ¡Sin aplicación! Tus ojos. En Hong Kong sabemos por fiesta.", "Mira la lluna aquesta nit. Grassa o prima? Creix o minva? Sense aplicació, amb els ulls! A Hong Kong ho sabíem per les festes."]);
X("c08", 2, "plaza", ["Sat on a bench for a quarter of an hour", "在长椅上坐了一刻钟", "在長椅上坐了一刻鐘", "Un cuarto de hora en un banco", "Un quart d'hora en un banc"],
 ["Sit on a bench in the park. Fifteen minutes. No phone, no book. Watch pigeons. Pigeons very dramatic one.", "去公园坐长椅。十五分钟。不看手机，不看书。看鸽子。鸽子好多戏。", "去公園張櫈坐十五分鐘，唔睇電話，唔睇書，睇白鴿。啲白鴿好多戲㗎。", "Siéntate en banco del parque. Quince minutos. Sin móvil, sin libro. Mira palomas. Palomas son muy dramáticas.", "Seu en un banc del parc quinze minuts. Sense mòbil ni llibre. Mira els coloms. Els coloms són molt dramàtics."]);
X("c09", 1, "", ["Stretched before bed", "睡前伸展了一下", "睡前伸展了一下", "Estiré antes de dormir", "Vaig estirar-me abans de dormir"],
 ["Before bed, stretch. Up, up, like reaching for the top shelf. Then down, touch toes. Or knees. Knees also OK lah.", "睡觉前，拉拉筋。上，上，像拿最高的架子。然后下，摸脚趾。或者膝盖。膝盖也行。", "瞓覺前拉下筋：向上、向上，好似攞最高層架嘅嘢噉。跟住彎落去掂腳趾，掂膝頭都得。", "Antes de cama, estira. Arriba, arriba, como alcanzar estante alto. Luego abajo, toca pies. O rodillas. Rodillas también vale.", "Abans d'anar a dormir, estira't. Amunt, amunt, com si volguessis arribar al prestatge de dalt. Després avall, a tocar els peus. O els genolls, que també val."],
 ["cats", ["*Yuzu demonstrates the correct stretch, very long, with a yawn at the end*", "*柚子示范了标准伸懒腰，拉得好长，最后打个哈欠*", "*柚子示範了標準伸懶腰，拉得好長，最後打個哈欠*", "*Yuzu enseña el estiramiento correcto, larguísimo, con bostezo al final*", "*Yuzu fa una demostració de com s'estira un bé, llarguíssim, amb un badall al final*"]]);
X("c10", 1, "", ["One meal in quiet", "安安静静吃了一顿饭", "安安靜靜吃了一頓飯", "Una comida en silencio", "Un àpat en silenci"],
 ["Eat one meal quiet. No TV, no phone. Taste the food! Somebody cook it. Maybe you. Respect ah.", "安安静静食一顿饭。不开电视，不看手机。尝尝味道！有人做的。可能是你。要尊重。", "靜靜哋食一餐飯，唔開電視，唔睇電話，好好試下啲味！有人煮㗎嘛，可能係你自己煮。要尊重下。", "Come una comida en silencio. Sin tele, sin móvil. ¡Saborea comida! Alguien la cocina. Quizás tú. Respeto.", "Fes un àpat en silenci. Sense tele ni mòbil. Tasta el menjar! Algú l'ha cuinat, potser tu mateix. Una mica de respecte."]);
X("c11", 1, "", ["Went a different way", "换了一条路走", "換了一條路走", "Fui por otra calle", "Vaig anar per un altre carrer"],
 ["Today, go different street. Same place, different way. You find a bakery maybe. Bring me something lah.", "今天走另一条街。同一个地方，换条路。可能你找到一家面包店。带一点给我。", "今日行第二條街，同一個地方，換條路行。可能會搵到間餅舖，記得帶嘢返嚟俾我。", "Hoy, ve por otra calle. Mismo sitio, otro camino. Quizás encuentras panadería. Tráeme algo.", "Avui, vés per un altre carrer. El mateix lloc, un altre camí. Potser trobes un forn. Porta'm alguna cosa."]);
X("c12", 1, "", ["Put my hand on a tree or a stone", "摸了一棵树或一块石头", "摸了一棵樹或一塊石頭", "Toqué un árbol o una piedra", "Vaig tocar un arbre o una pedra"],
 ["Touch a tree. Or old stone wall. With hand! Rough, cold, very old. Older than me even. Imagine.", "摸一棵树。或者旧石墙。用手！粗粗的，凉凉的，好老。比我还老。想想。", "去摸下棵樹，或者一幅舊石牆，用手摸呀！粗粗哋、凍冰冰，好老㗎，仲老過我，諗下都得意。", "Toca un árbol. O pared de piedra vieja. ¡Con mano! Áspero, frío, muy viejo. Más viejo que yo. Imagina.", "Toca un arbre, o un mur de pedra vella. Amb la mà! Aspre, fred, molt antic. Més vell que jo i tot. Imagina't."]);
X("c13", 3, "sea", ["Swam outdoors", "在户外游了泳", "在戶外游了泳", "Nadé al aire libre", "Vaig nedar a l'aire lliure"],
 ["Swim outside. Sea, lake, river. Cold! Scream a little, it's fine lah. Barceloneta in June, I swim every Sunday. Hat after.", "去外面游泳。海，湖，河。好冷！叫两声冇关系。六月的巴塞罗内塔，我礼拜天都去游。游完戴帽子。", "去出面游水：海、湖、河都得。凍到嗌出聲？冇問題㗎。六月嘅巴塞羅內塔，我逢星期日都去游。游完記得戴帽。", "Nada fuera. Mar, lago, río. ¡Frío! Grita un poco, no pasa nada. Barceloneta en junio, yo nado cada domingo. Gorro después.", "Neda a fora: al mar, al llac, al riu. Fred! Crida una mica, no passa res. Al juny, a la Barceloneta, jo nedava cada diumenge. I després, barret."]);
X("c14", 1, "", ["Named five sounds around me", "说出了身边五种声音", "說出了身邊五種聲音", "Nombré cinco sonidos a mi alrededor", "Vaig dir cinc sons del meu voltant"],
 ["Close eyes. Listen. Say five sounds. Bird, car, neighbour shouting, fridge, your own tummy. Hungry ah? Eat!", "闭上眼。听。说五种声音。鸟，车，邻居吵架，冰箱，你自己的肚子。饿？食饭啦！", "閂埋對眼，聽下，講五種聲出嚟：雀仔、架車、隔籬鄰舍嗌交、雪櫃、你個肚。肚餓？食嘢啦！", "Cierra ojos. Escucha. Di cinco sonidos. Pájaro, coche, vecino gritando, nevera, tu propia barriga. ¿Hambre? ¡Come!", "Tanca els ulls i escolta. Digues cinc sons: un ocell, un cotxe, el veí cridant, la nevera, la teva panxa. Tens gana? Doncs menja!"]);
X("c15", 1, "", ["A glass of water before coffee", "喝咖啡前先喝一杯水", "喝咖啡前先喝一杯水", "Un vaso de agua antes del café", "Un got d'aigua abans del cafè"],
 ["Morning, glass of water first. Warm is best. Then your coffee, your tea, OK. Body is like plant, water first.", "早上先喝杯水。温的最好。然后咖啡，茶，都行。身体像植物，先浇水。", "朝早先飲杯水，暖水最好。之後飲咖啡飲茶都得。個身好似棵植物噉，要先淋水。", "Mañana, vaso de agua primero. Templada es mejor. Luego tu café, tu té, vale. Cuerpo es como planta, agua primero.", "Al matí, primer un got d'aigua, millor tèbia. Després el cafè o el te, el que vulguis. El cos és com una planta: primer, aigua."],
 ["mei", ["Hot water, the Chinese grandmother cure for everything. Broken heart? Hot water.", "热水，中国外婆万能药。心碎了？喝热水。", "熱水，華人外婆萬靈丹。心碎了？喝熱水。", "Agua caliente, la cura de las abuelas chinas para todo. ¿Corazón roto? Agua caliente.", "Aigua calenta, el remei de les àvies xineses per a tot. Cor trencat? Aigua calenta."]]);
X("c16", 2, "bar", ["Cooked from whole ingredients", "用原材料做了一顿饭", "用原材料做了一頓飯", "Cociné con ingredientes de verdad", "Vaig cuinar amb ingredients de debò"],
 ["Cook from real things. Vegetable, rice, egg. Nothing from a box with long words. If I can't say it, don't eat it lah.", "用真东西做饭。菜，米，蛋。不要盒子里那些名字长长的。我念不出来的，不要食。", "用真材實料煮飯：菜、米、蛋。唔好用嗰啲盒裝、成串長名嘅嘢。我讀唔出嘅，唔好食。", "Cocina con cosas reales. Verdura, arroz, huevo. Nada de caja con palabras largas. Si yo no puedo decir, no comas.", "Cuina amb coses de veritat: verdura, arròs, ous. Res de capses amb paraules llargues. Si jo no ho sé pronunciar, no t'ho mengis."]);
X("c17", 3, "", ["Kneaded dough with my hands", "用手揉了面团", "用手揉了麵團", "Amasé con las manos", "Vaig pastar amb les mans"],
 ["Make dough. Flour, water, push, fold, push. Ten minutes. Angry? Push harder. Bread don't mind.", "揉面。面粉，水，推，折，推。十分钟。生气？用力推。面包不介意的。", "搓個麵糰：麵粉、水，推、摺、推，搓十分鐘。嬲緊？大力啲搓，個包唔介意㗎。", "Haz masa. Harina, agua, empuja, dobla, empuja. Diez minutos. ¿Enfadado? Empuja más fuerte. Al pan no le importa.", "Fes una massa: farina, aigua, empeny, plega, empeny. Deu minuts. Que estàs enfadat? Empeny més fort. Al pa no li fa res."]);
X("c18", 2, "", ["Listened to the rain", "听了一会儿雨", "聽了一會兒雨", "Escuché la lluvia", "Vaig escoltar la pluja"],
 ["When it rain, stop. Sit by window. Listen. Rain has many sounds: on roof, on car, on umbrella. Free music wor.", "下雨的时候，停下来。坐窗口。听。雨有好多声音：屋顶，车顶，伞上面。免费音乐。", "落雨嗰陣停一停，坐喺窗邊聽下。啲雨有好多種聲：打落屋頂、車頂、遮度，免費音樂嚟㗎。", "Cuando llueve, para. Siéntate en ventana. Escucha. Lluvia tiene muchos sonidos: en tejado, en coche, en paraguas. Música gratis.", "Quan plogui, para. Seu a la finestra i escolta. La pluja té molts sons: a la teulada, al cotxe, al paraigua. Música de franc."]);
X("c19", 3, "garden", ["Started composting", "开始堆肥", "開始堆肥", "Empecé a compostar", "Vaig començar a fer compost"],
 ["Peels, egg shells, coffee: don't throw! Make compost. Old food become new soil. Like me, I am old, but still useful one.", "果皮，蛋壳，咖啡渣：不要扔！做堆肥。旧食物变新泥土。像我，老了，但是有用。", "啲果皮、蛋殼、咖啡渣，唔好掉！整堆肥。舊嘢食變新泥土，好似我噉，老就老，不過仲有用。", "Peladuras, cáscaras de huevo, café: ¡no tires! Haz compost. Comida vieja se hace tierra nueva. Como yo, soy vieja, pero útil.", "Peles, closques d'ou, pòsit de cafè: no ho llencis! Fes compost. El menjar vell es torna terra nova. Com jo: soc vella, però faig servei."]);
X("c20", 3, "", ["Dried the washing on a line", "把衣服晾在绳子上", "把衣服晾在繩子上", "Tendí la ropa al sol", "Vaig estendre la roba al sol"],
 ["Hang washing outside, in sun. Machine dryer, no. Sun is free, smell is better. Barcelona got so much sun, use it!", "衣服晾外面，晒太阳。烘干机，不要。太阳免费，味道更好。巴塞罗那这么多太阳，用啦！", "啲衫晾出去曬太陽，唔好用乾衣機。太陽唔使錢，啲衫仲香啲。巴塞隆拿咁多太陽，唔用就嘥喇！", "Tiende ropa fuera, al sol. Secadora, no. Sol es gratis, olor es mejor. Barcelona tiene tanto sol, ¡úsalo!", "Estén la roba a fora, al sol. Assecadora, no. El sol és de franc i la roba fa més bona olor. A Barcelona hi ha tant de sol, aprofita'l!"]);
X("c21", 1, "", ["Three slow breaths at the door", "在门口慢慢呼吸三次", "在門口慢慢呼吸三次", "Tres respiraciones lentas en la puerta", "Tres respiracions lentes a la porta"],
 ["Before you go in the house, stop at the door. Three slow breath. Out, out, out. Leave the outside outside.", "进门之前，在门口停一停。慢慢吸三口气。呼，呼，呼。外面的事留在外面。", "入屋之前喺門口停一停，慢慢呼三啖氣：呼、呼、呼。出面啲嘢，留喺出面。", "Antes de entrar en casa, para en puerta. Tres respiraciones lentas. Fuera, fuera, fuera. Deja lo de fuera fuera.", "Abans d'entrar a casa, atura't a la porta. Tres respiracions lentes: fora, fora, fora. El que és de fora, que es quedi fora."]);
X("c22", 3, "cabin", ["Tended a fire", "照看了一堆火", "照看了一堆火", "Cuidé un fuego", "Vaig cuidar un foc"],
 ["Make a fire, wood one. Fireplace, camping, anywhere safe. Then you sit and look. Fire is the first TV lor.", "生个火，烧柴的。壁炉，露营，安全的地方都行。然后坐下看着。火是第一台电视。", "生個火，燒柴嗰種。壁爐、露營，安全嘅地方就得。之後坐低睇住佢。火係世上第一部電視嚟㗎。", "Haz fuego, de leña. Chimenea, camping, sitio seguro. Luego te sientas y miras. El fuego es la primera tele.", "Fes un foc de llenya, a la llar, d'acampada o on sigui segur. Després seus i mires. El foc va ser la primera tele."],
 ["wei", ["Popo lights the stove at No Hurry with one match. Every time. I've stopped asking how.", "婆婆在“不急”生炉子只用一根火柴。每次都是。我已经不问怎么做到的了。", "婆婆在「不急」生爐子只用一根火柴。每次都是。我已經不問怎麼做到的了。", "Popo enciende la estufa de Sin Prisa con una cerilla. Siempre. Ya no pregunto cómo.", "La Popo encén l'estufa de Sense Pressa amb un sol llumí. Sempre. Ja no li pregunto com."]]);
X("c23", 3, "pasture", ["Picked fruit at a farm", "去农场摘了水果", "去農場摘了水果", "Recogí fruta en una granja", "Vaig collir fruita en una granja"],
 ["Go to farm, pick fruit yourself. Strawberry, cherry, apple. Eat one, pick one, eat one. Farmer knows. Farmer don't mind.", "去农场自己摘水果。草莓，樱桃，苹果。吃一个，摘一个，再吃一个。农夫知道的。农夫不介意。", "去農場自己摘生果：士多啤梨、車厘子、蘋果。食一粒，摘一粒，再食一粒。農夫知㗎，佢唔介意。", "Ve a granja, recoge fruta tú mismo. Fresa, cereza, manzana. Come una, coge una, come una. Granjero sabe. No le importa.", "Vés a una granja i cull la fruita tu mateix: maduixes, cireres, pomes. En menges una, en culls una, en menges una altra. El pagès ja ho sap, i no li fa res."]);
X("c24", 2, "", ["Lay with my legs up the wall", "把腿靠墙躺了一会儿", "把腿靠牆躺了一會兒", "Me tumbé con las piernas en la pared", "Em vaig estirar amb les cames a la paret"],
 ["Lie on floor, legs up the wall. Ten minutes. Feet tired all day, now they rest on top. Very good for old ladies. And young also.", "躺地上，两只脚放墙上。十分钟。脚累了一整天，现在在上面休息一下。对老太太好。对年轻人也好。", "瞓喺地下，對腳挨上牆，十分鐘。對腳攰咗成日，而家換佢喺上面唞下。對老人家好好，後生都啱。", "Túmbate en suelo, piernas en pared. Diez minutos. Pies cansados todo el día, ahora descansan arriba. Muy bueno para viejitas. Y jóvenes.", "Estira't a terra amb les cames enlaire contra la paret. Deu minuts. Els peus han treballat tot el dia; ara descansen a dalt. Molt bo per a les velles. I per als joves."],
 ["mantou", ["*Mantou lies down beside you, legs also in the air, for solidarity*", "*馒头在你旁边躺下，四条腿也朝天，以示团结*", "*饅頭在你旁邊躺下，四條腿也朝天，以示團結*", "*Mantou se tumba a tu lado, también patas arriba, por solidaridad*", "*Mantou s'estira al teu costat, també panxa enlaire, per solidaritat*"]]);
X("c25", 3, "", ["Found north without a phone", "不用手机找到了北边", "不用手機找到了北邊", "Encontré el norte sin móvil", "Vaig trobar el nord sense mòbil"],
 ["Find north. No phone ah! Sun get up in the east, go down in the west. Josep teach me with his watch. Clever man, my Josep.", "找北边。不用手机！太阳东边出，西边落。Josep 用他的表教我。聪明人，我的 Josep。", "搵北面，唔准用電話！太陽東邊出，西邊落。Josep 以前用佢隻錶教我，好叻㗎，我個 Josep。", "Encuentra el norte. ¡Sin móvil! Sol sale por el este, se pone por el oeste. Josep me enseñó con su reloj. Listo, mi Josep.", "Troba el nord. Sense mòbil! El sol surt per l'est i es pon per l'oest. En Josep m'ho va ensenyar amb el rellotge. Que llest era, el meu Josep."]);

/* ---------- 4 · Alone, together, and slowly ---------- */
X("d01", 2, "postcard", ["Wrote a postcard by hand", "手写了一张明信片", "手寫了一張明信片", "Escribí una postal a mano", "Vaig escriure una postal a mà"],
 ["Write a postcard lah. With hand, with stamp. Your friend open the mailbox, there is you! Not a bill. You!", "写张明信片。用手写，贴邮票。你朋友开信箱，是你！不是账单。是你！", "寫張明信片，手寫、貼郵票。你個朋友打開信箱，見到你！唔係單，係你呀！", "Escribe una postal. Con mano, con sello. Tu amigo abre buzón, ¡estás tú! No factura. ¡Tú!", "Escriu una postal, a mà i amb segell. La teva amiga obre la bústia i hi ets tu! No una factura: tu!"],
 ["mei", ["She's mailed postcards to New York for thirty years. Mum keeps every single one in a shoebox. Don't tell her I told you.", "她往纽约寄了三十年明信片。我妈每一张都收在一个鞋盒里。别说是我说的。", "她往紐約寄了三十年明信片。我媽每一張都收在一個鞋盒裡。別說是我說的。", "Lleva treinta años mandando postales a Nueva York. Mamá las guarda todas en una caja de zapatos. No digas que te lo he contado.", "Fa trenta anys que envia postals a Nova York. La mare les guarda totes en una capsa de sabates. No diguis que t'ho he dit."]]);
X("d02", 1, "", ["Asked someone how their day was, and meant it", "真心问了别人今天过得怎样", "真心問了別人今天過得怎樣", "Pregunté a alguien qué tal su día, de verdad", "Vaig preguntar a algú com li anava el dia, de debò"],
 ["When you buy coffee, ask the person: how is your day? And listen! They make hundred coffee. Nobody ask one.", "买咖啡的时候，问那个人：你今天好吗？还要听！他们冲一百杯咖啡。冇人问。", "買咖啡嗰陣，問下個伙計：「你今日點呀？」仲要聽佢講！佢哋一日沖成百杯，冇人問㗎。", "Cuando compras café, pregunta a la persona: ¿qué tal tu día? ¡Y escucha! Hace cien cafés. Nadie pregunta.", "Quan compris el cafè, pregunta a qui te'l fa: com t'està anant el dia? I escolta! Fa cent cafès al dia i ningú no li ho pregunta."],
 ["mei", ["As someone who made coffee at Next Door: please. Ask. Also don't drink mine.", "作为在“隔壁”做过咖啡的人：拜托。问一下。还有别喝我做的。", "作為在「隔壁」做過咖啡的人：拜託。問一下。還有別喝我做的。", "Como alguien que ha hecho café en Al Lado: por favor. Preguntad. Y no os bebáis el mío.", "Com a persona que ha fet cafè a Al Costat: si us plau. Pregunteu. I no us begueu el meu."]]);
X("d03", 3, "party", ["Dinner with the phones in a basket", "手机放篮子里吃了顿饭", "手機放籃子裡吃了頓飯", "Una cena con los móviles en una cesta", "Un sopar amb els mòbils en una cistella"],
 ["Invite people for dinner lah. Basket at the door, phones inside. Like guns in cowboy film! Then you talk. Real talk.", "请人来家里食饭。门口放个篮子，手机放进去。像牛仔电影里放枪！然后聊天。真的聊。", "請人嚟食飯，門口擺個籃，啲電話全部放入去，好似牛仔片除槍噉！跟住就傾偈，真真正正噉傾。", "Invita gente a cenar. Cesta en la puerta, móviles dentro. ¡Como pistolas en película de vaqueros! Luego hablas. De verdad.", "Convida gent a sopar. Una cistella a la porta, i els mòbils a dins, com les pistoles a les pel·lícules de l'Oest! I després, a parlar. Parlar de debò."],
 ["wei", ["Come Over can make the invitation, if you'd like a little help with who's bringing what.", "想让别人帮忙分配谁带什么的话，“来我家”可以做邀请。", "想讓別人幫忙分配誰帶什麼的話，「來我家」可以做邀請。", "Ven a Casa puede hacer la invitación, si quieres ayuda con quién trae qué.", "Vine a Casa pot fer la invitació, si vols un cop de mà amb qui porta què."]]);
X("d04", 3, "books", ["Wandered a library with no plan", "漫无目的地逛了图书馆", "漫無目的地逛了圖書館", "Paseé por una biblioteca sin plan", "Vaig passejar per una biblioteca sense pla"],
 ["Go to the library. No plan! Walk, touch books. Take the one with the funny cover. Free! Wah, still free.", "去图书馆。不用计划！走走，摸摸书。拿本封面好笑的。免费！到现在还免费。好厉害。", "去圖書館，唔使有計劃！行下、摸下啲書，揀本封面最得意嗰本。唔使錢㗎！到而家都唔使錢，犀利。", "Ve a biblioteca. ¡Sin plan! Camina, toca libros. Coge el de portada graciosa. ¡Gratis! Todavía gratis. Increíble.", "Vés a la biblioteca. Sense pla! Passeja, toca els llibres, agafa el de la coberta més divertida. De franc! Encara és de franc. Increïble."]);
X("d05", 3, "hall", ["Made something with my hands", "动手做了一样东西", "動手做了一樣東西", "Hice algo con las manos", "Vaig fer alguna cosa amb les mans"],
 ["Make something with hands. Knit, clay, wood, paper. Crooked is fine. My first scarf, Josep wear it ten years. Very ugly one.", "用手做点东西。织毛线，捏泥，木头，纸。歪歪的也行。我第一条围巾，Josep 戴了十年。好丑。", "用手整啲嘢：織冷、搓泥、木、紙都得。歪歪哋唔緊要。我織嘅第一條頸巾，Josep 戴咗十年，醜到死。", "Haz algo con manos. Tejer, barro, madera, papel. Torcido está bien. Mi primera bufanda, Josep la llevó diez años. Muy fea.", "Fes alguna cosa amb les mans: mitja, fang, fusta, paper. Si queda torta, no passa res. La meva primera bufanda, en Josep la va portar deu anys. Horrorosa."],
 ["wei", ["There's a quilt at Town Hall that anyone can add one square to. Hers is the crooked one.", "“镇公所”有一床被子，谁都可以缝一块。她的那块是歪的。", "「鎮公所」有一床被子，誰都可以縫一塊。她的那塊是歪的。", "En el Ayuntamiento hay una colcha a la que cualquiera puede añadir un cuadrado. El suyo es el torcido.", "A l'Ajuntament hi ha un edredó on tothom pot afegir-hi un quadre. El seu és el tort."]]);
X("d06", 2, "restaurant", ["A ten-minute phone call", "打了一个十分钟的电话", "打了一通十分鐘的電話", "Una llamada de diez minutos", "Una trucada de deu minuts"],
 ["Call somebody. With voice! Ten minutes. Your mama, your friend, your old teacher. Typing is not talking ah.", "打个电话给人。用声音！十分钟。你妈妈，你朋友，你以前的老师。打字不是说话。", "打個電話俾人，用把聲呀！十分鐘：阿媽、朋友、以前個老師都得。打字唔係傾偈㗎。", "Llama a alguien. ¡Con voz! Diez minutos. Tu mamá, tu amigo, tu profesor viejo. Escribir no es hablar.", "Truca a algú. Amb la veu! Deu minuts. La teva mare, una amiga, aquella mestra. Escriure no és parlar."],
 ["mei", ["The ONE time she wants me on the phone. Fine. Calling my mum. Don't watch.", "她唯一一次希望我拿起手机。行。我给我妈打。别看。", "她唯一一次希望我拿起手機。好啦。我打給我媽。別看。", "La ÚNICA vez que quiere que use el móvil. Vale. Llamo a mi madre. No miréis.", "L'ÚNICA vegada que vol que agafi el mòbil. Vale. Truco a la mare. No mireu."]]);
X("d07", 3, "", ["Helped clean up the neighbourhood", "帮忙清理了街区", "幫忙清理了街區", "Ayudé a limpiar el barrio", "Vaig ajudar a netejar el barri"],
 ["Clean up your street. Or park, or beach. Bring bag, gloves. People see you, they come help. Or say thank you. Both good.", "把你的街扫干净。或者公园，或者沙滩。带袋子，手套。别人看到，会来帮忙。或者说多谢。都好。", "去執下你條街，或者公園、海灘。帶個袋、對手套。啲人見到你，會嚟幫手，或者同你講聲多謝，兩樣都好。", "Limpia tu calle. O parque, o playa. Trae bolsa, guantes. Gente te ve, viene ayudar. O dice gracias. Ambos bien.", "Neteja el teu carrer, o el parc, o la platja. Porta una bossa i guants. La gent et veu i ve a ajudar, o et dona les gràcies. Totes dues coses estan bé."]);
X("d08", 3, "", ["Learnt a short poem by heart", "背下了一首短诗", "背下了一首短詩", "Me aprendí un poema corto", "Vaig aprendre un poema curt de memòria"],
 ["Learn a short poem by heart. Four lines. Then it live in you. Nobody can delete one. I still know Li Bai from school.", "背一首短诗。四句。然后它住在你心里。谁也删不掉。我读书时背的李白，还记得。", "背首短詩，四句就夠。背咗就住喺你心入面，冇人刪得走。我細個讀書背嘅李白，到而家都記得。", "Aprende un poema corto de memoria. Cuatro líneas. Luego vive en ti. Nadie puede borrar. Yo aún sé Li Bai del colegio.", "Aprèn-te un poema curt de memòria. Quatre versos. Després viu dins teu i ningú no el pot esborrar. Jo encara sé el Li Bai de l'escola."]);
X("d09", 2, "", ["Wrote down what I'd done today", "写下今天做完的事", "寫下今天做完的事", "Apunté lo que hice hoy", "Vaig apuntar el que havia fet avui"],
 ["Night, write what you did today. Not what you didn't! What you did. Wash hair? Write. Call mama? Write. Good day.", "晚上，写今天做了什么。不是没做的！是做了的。洗了头？写。打给妈妈？写。好日子。", "夜晚寫低今日做咗乜，唔係寫未做嘅！係做咗嘅。洗咗頭？寫。打咗俾阿媽？寫。今日都唔錯喎。", "Noche, escribe qué hiciste hoy. ¡No lo que no! Lo que sí. ¿Lavaste pelo? Escribe. ¿Llamaste a mamá? Escribe. Buen día.", "A la nit, escriu el que has fet avui. No el que no has fet! El que sí. T'has rentat els cabells? Apunta-ho. Has trucat a la mare? Apunta-ho. Bon dia, doncs."]);
X("d10", 3, "", ["Filled a box to give away", "装了一箱东西送人", "裝了一箱東西送人", "Llené una caja para dar", "Vaig omplir una capsa per donar"],
 ["Box by the door. Things you don't use, put in. Full? Give away. Somebody need your old coat more than your closet lor.", "门口放个箱子。不用的东西放进去。满了？送人。别人比你的衣柜更需要你那件旧外套。", "門口擺個箱，唔用嘅嘢擺入去。滿咗就攞去送人。有人需要你件舊褸，多過你個衣櫃需要佢。", "Caja junto a puerta. Cosas que no usas, mete. ¿Llena? Regala. Alguien necesita tu abrigo viejo más que tu armario.", "Una capsa a la porta. Hi poses el que no fas servir. Quan és plena, la dones. Algú necessita el teu abric vell més que el teu armari."]);
X("d11", 3, "", ["Drew one thing I could see", "画了一样眼前的东西", "畫了一樣眼前的東西", "Dibujé algo que tenía delante", "Vaig dibuixar una cosa que tenia davant"],
 ["Draw something on the table. A cup, a shoe, an onion. Bad drawing is OK lah! You look at it so long, you see it new.", "画桌上的东西。一个杯子，一只鞋，一个洋葱。画得丑也行！看那么久，你就看到它新的样子。", "畫枱面上一樣嘢：個杯、隻鞋、個洋蔥都得。畫得醜唔緊要！望得耐，你會見到佢新嘅一面。", "Dibuja algo en la mesa. Una taza, un zapato, una cebolla. ¡Dibujo feo está bien! Lo miras tanto, lo ves nuevo.", "Dibuixa alguna cosa de la taula: una tassa, una sabata, una ceba. Si queda lleig, no passa res! De tant mirar-la, la veus com nova."],
 ["cats", ["*Miso walks across the paper and adds four little paw prints*", "*味噌从纸上走过，添了四个小爪印*", "*味噌從紙上走過，添了四個小爪印*", "*Miso cruza el papel y añade cuatro huellitas*", "*Miso travessa el paper i hi afegeix quatre petjades*"]]);
X("d12", 2, "story", ["Asked someone older for a story", "请长辈讲了一个故事", "請長輩講了一個故事", "Pedí una historia a alguien mayor", "Vaig demanar una història a algú gran"],
 ["Ask an old person for a story. Your grandma, the man downstairs. \"How was it before?\" Then sit. Long story. Very long one.", "请老人家讲个故事。你外婆，楼下的老伯。“以前是怎样的？”然后坐下。故事好长。好长好长。", "叫個老人家講個故仔：你婆婆、樓下個伯伯都得。問佢：「以前係點㗎？」跟住坐定定，個故會好長，好長好長。", "Pide a persona mayor una historia. Tu abuela, el señor de abajo. \"¿Cómo era antes?\" Luego siéntate. Historia larga. Muy larga.", "Demana una història a algú gran: la teva àvia, el senyor del primer. «Com era abans?» I després seu. La història serà llarga. Llarguíssima."],
 ["wei", ["Hers starts on a train in 1968. It's on the shelf, if you'd like it.", "她的故事从一九六八年的一列火车开始。在架子上，你想看的话。", "她的故事從一九六八年的一列火車開始。在架子上，你想看的話。", "La suya empieza en un tren en 1968. Está en la estantería, si la quieres.", "La seva comença en un tren el 1968. És a la lleixa, si la vols."]]);
X("d13", 3, "", ["Bought from the person who made it", "从做东西的人手里买了东西", "從做東西的人手裡買了東西", "Compré a quien lo hizo", "Vaig comprar a qui ho havia fet"],
 ["Go to market. Buy from the one who make it. Cheese man, honey lady. Ask how. They tell you everything wor.", "去市场。跟做东西的人买。做奶酪的大叔，卖蜂蜜的阿姨。问怎么做。他们什么都告诉你。", "去街市，同整嘢嗰個人買：整芝士嘅阿叔、賣蜜糖嘅阿姐。問佢點整，佢會乜都話晒你知。", "Ve al mercado. Compra al que lo hace. Señor del queso, señora de la miel. Pregunta cómo. Te cuentan todo.", "Vés al mercat i compra a qui ho fa: el del formatge, la de la mel. Pregunta'ls com ho fan. T'ho explicaran tot."]);
X("d14", 3, "books", ["Left a note in a shared book", "在共享书里留了一张字条", "在共享書裡留了一張字條", "Dejé una nota en un libro compartido", "Vaig deixar una nota en un llibre compartit"],
 ["Little library box on the street? Put a book, with a note inside. \"Hope you like.\" Somebody find it, smile.", "街上的小书箱？放本书，里面夹张小纸条。“希望你喜欢。”有人找到，会笑。", "街邊有個小書箱？放本書入去，夾張紙仔：「希望你鍾意。」有人執到，會笑㗎。", "¿Cajita de libros en la calle? Pon un libro, con nota dentro. \"Espero que te guste.\" Alguien encuentra, sonríe.", "Hi ha una caseta de llibres al carrer? Deixa-hi un llibre amb una nota a dins: «Espero que t'agradi». Algú la trobarà i somriurà."],
 ["wei", ["Borrowed Pages has a shelf like that, if there isn't a box on your street yet.", "如果你那条街还没有书箱，“借来的书”有个这样的架子。", "如果你那條街還沒有書箱，「借來的書」有個這樣的架子。", "Páginas Prestadas tiene un estante así, si en tu calle aún no hay cajita.", "Pàgines Manllevades té un prestatge així, si al teu carrer encara no hi ha caseta."]]);
X("d15", 3, "jukebox", ["Played music just for the room", "弹了一段只给屋子听的音乐", "彈了一段只給屋子聽的音樂", "Toqué música solo para la habitación", "Vaig tocar música només per a l'habitació"],
 ["Play your instrument. Don't record! Nobody need to see. Wrong note? Only the walls know lor. Walls keep secrets.", "弹你的乐器。不要录！冇人要看。弹错？只有墙知道。墙会保密的。", "彈下你件樂器，唔好錄！唔使俾人睇。彈錯音？得幅牆知，牆識守秘密㗎。", "Toca tu instrumento. ¡No grabes! Nadie necesita ver. ¿Nota mala? Solo las paredes saben. Paredes guardan secretos.", "Toca el teu instrument. No el gravis! No cal que ho vegi ningú. Una nota falsa? Només ho saben les parets, i les parets guarden secrets."]);
X("d16", 3, "", ["A jigsaw on the side table", "边桌上摆了一盒拼图", "邊桌上擺了一盒拼圖", "Un puzle en la mesita", "Un trencaclosques a la tauleta"],
 ["Jigsaw on small table. Not finish in one day! Each time you pass, one piece. One month later, wah, a mountain.", "小桌上摆拼图。不要一天拼完！每次走过，放一块。一个月以后：一座山。", "張細枱擺盒砌圖，唔好一日砌晒！每次行過就砌一塊，一個月後：一座山。", "Puzle en mesa pequeña. ¡No acabes en un día! Cada vez que pasas, una pieza. Un mes después: una montaña.", "Un trencaclosques a la tauleta. No l'acabis en un dia! Cada cop que hi passes, una peça. Al cap d'un mes: una muntanya."],
 ["cats", ["*Yuzu has taken one piece somewhere. It will turn up in spring.*", "*柚子把一块拼图藏到了某个地方。春天会出现的。*", "*柚子把一塊拼圖藏到了某個地方。春天會出現的。*", "*Yuzu se ha llevado una pieza a algún sitio. Aparecerá en primavera.*", "*Yuzu s'ha endut una peça no se sap on. Apareixerà a la primavera.*"]]);
X("d17", 3, "", ["Learnt my neighbours' names", "记住了邻居的名字", "記住了鄰居的名字", "Aprendí los nombres de mis vecinos", "Vaig aprendre el nom dels meus veïns"],
 ["Learn names of your neighbours. Next door, upstairs. Say \"Good morning, Mrs Puig\". Name is like key. Open door.", "记住邻居的名字。隔壁的，楼上的。说“早上好，Puig 太太”。名字像钥匙。开门的。", "記住你啲街坊個名：隔籬、樓上。講句「早晨，Puig 太」。個名好似鎖匙噉，開到門㗎。", "Aprende nombres de tus vecinos. Al lado, arriba. Di \"Buenos días, señora Puig\". Nombre es como llave. Abre puerta.", "Aprèn el nom dels teus veïns: els del costat, els de dalt. Digues «Bon dia, senyora Puig». Un nom és com una clau: obre portes."]);
X("d18", 3, "", ["A shower by candlelight", "点着蜡烛洗了个澡", "點著蠟燭洗了個澡", "Una ducha a la luz de una vela", "Una dutxa a la llum d'una espelma"],
 ["Shower with candle, no big light. Warm, dark, quiet. Like a little temple. Don't put candle near towel ah!", "点蜡烛洗澡，不开大灯。暖，暗，静。像个小庙。蜡烛不要放毛巾旁边！", "點枝蠟燭沖涼，唔開大燈。暖暖哋、暗暗哋、靜靜哋，好似間小廟噉。蠟燭唔好擺近毛巾呀！", "Ducha con vela, sin luz grande. Caliente, oscuro, tranquilo. Como un templo pequeño. ¡No pongas vela cerca de toalla!", "Dutxa't amb una espelma, sense el llum gran. Calent, fosc, tranquil, com un temple petit. Però no posis l'espelma a prop de la tovallola!"]);
X("d19", 3, "kintsugi", ["Mended something instead of replacing it", "修好了东西，没换新的", "修好了東西，沒換新的", "Arreglé algo en vez de cambiarlo", "Vaig arreglar una cosa en lloc de canviar-la"],
 ["Something broken? Fix first. Glue, tape, needle, ask a neighbour. New one is easy. Fixed one got a story.", "东西坏了？先修。胶水，胶带，针，问邻居。买新的容易。修好的，有故事。", "有嘢壞咗？先試下整返好：膠水、膠紙、針線，或者問下街坊。買新嗰個易，整返好嗰個先有故事。", "¿Algo roto? Arregla primero. Pegamento, cinta, aguja, pregunta a vecino. Nuevo es fácil. Arreglado tiene historia.", "S'ha trencat alguna cosa? Primer, prova d'arreglar-la: cola, cinta, agulla, o pregunta al veí. Una de nova és fàcil. Una d'arreglada té història."],
 ["wei", ["There's a bowl in her kitchen with a gold line across it. Ask her about it some day.", "她厨房里有只碗，上面有一道金线。哪天问问她。", "她廚房裡有只碗，上面有一道金線。哪天問問她。", "En su cocina hay un cuenco con una línea de oro. Pregúntale algún día.", "A la seva cuina hi ha un bol amb una línia d'or. Pregunta-li'n algun dia."]]);
X("d20", 2, "", ["Cleared the counters before bed", "睡前把台面收拾干净", "睡前把檯面收拾乾淨", "Despejé la encimera antes de dormir", "Vaig deixar el marbre net abans de dormir"],
 ["Before sleep, clean the kitchen counter. All of it. Morning you come in, so nice! Like somebody take care of you. It's you lah.", "睡觉前，把厨房台面收干净。全部。早上一进来，好舒服！像有人照顾你。就是你自己。", "瞓覺前執乾淨個廚房枱面，全部執晒。朝早一入嚟，好舒服！好似有人照顧緊你噉，其實係你自己。", "Antes de dormir, limpia la encimera. Toda. Por la mañana entras, ¡qué bonito! Como si alguien te cuida. Eres tú.", "Abans d'anar a dormir, deixa el marbre de la cuina ben net. Tot. Al matí hi entres i quin gust! És com si algú et cuidés. I ets tu."]);
X("d21", 3, "cabin", ["Ten minutes with one painting or one plant", "对着一幅画或一棵植物待了十分钟", "對著一幅畫或一棵植物待了十分鐘", "Diez minutos con un cuadro o una planta", "Deu minuts amb un quadre o una planta"],
 ["Look at one painting, or one plant, ten minutes. Only that. First minute boring. Fifth minute, wah, a little bug.", "看一幅画，或者一棵植物，十分钟。只看这个。第一分钟好闷。第五分钟，你看到一只小虫。", "望住一幅畫或者一棵植物，十分鐘，淨係望佢。第一分鐘好悶，第五分鐘，你會見到隻小蟲。", "Mira un cuadro, o una planta, diez minutos. Solo eso. Primer minuto aburrido. Quinto minuto, ves un bichito.", "Mira un quadre, o una planta, deu minuts. Només això. El primer minut és avorrit. Al cinquè, hi veus un bitxet."]);
X("d22", 3, "bar", ["Baked double and gave half away", "烤了双份，送了一半", "烤了雙份，送了一半", "Horneé el doble y regalé la mitad", "Vaig coure el doble i en vaig regalar la meitat"],
 ["Bake, but make double. Half for you, half for neighbour. Same work! Double happy. This is Popo math.", "烤东西，做两份。一半给你，一半给邻居。一样的功夫！双倍开心。这是婆婆数学。", "焗嘢就焗雙份，一半你食，一半送街坊。做嘅嘢一樣多，開心就雙倍。呢個係婆婆數學。", "Hornea, pero haz doble. Mitad para ti, mitad para vecino. ¡Mismo trabajo! Doble feliz. Esto es matemática de Popo.", "Cou alguna cosa, però fes-ne el doble. La meitat per a tu, la meitat per al veí. La mateixa feina i el doble d'alegria. Matemàtiques de la Popo."],
 ["mantou", ["*Mantou offers to carry the neighbour's half. He cannot be trusted with it.*", "*馒头主动要帮忙送邻居那一半。不能信它。*", "*饅頭主動要幫忙送鄰居那一半。不能信牠。*", "*Mantou se ofrece a llevar la mitad del vecino. No es de fiar.*", "*Mantou s'ofereix a portar la meitat del veí. No és de fiar.*"]]);
X("d23", 2, "", ["Three things I felt before sleep", "睡前想三件感受到的事", "睡前想三件感受到的事", "Tres cosas que sentí antes de dormir", "Tres coses que vaig sentir abans de dormir"],
 ["In bed, think three things from today: one you smell, one you hear, one you touch. Mine: garlic, Mantou snore, warm bowl.", "躺在床上，想今天三样东西：一样你闻到，一样你听到，一样你摸到。我的：蒜头，馒头打呼噜，暖暖的碗。", "瞓喺床度，諗今日三樣嘢：一樣聞到、一樣聽到、一樣摸到嘅。我嘅係：蒜頭、饅頭扯鼻鼾、一隻暖碗。", "En cama, piensa tres cosas de hoy: una que hueles, una que oyes, una que tocas. Las mías: ajo, Mantou ronca, cuenco caliente.", "Al llit, pensa tres coses d'avui: una que has olorat, una que has sentit i una que has tocat. Les meves: all, en Mantou roncant i un bol calent."]);
X("d24", 2, "cabin", ["Fifteen minutes of being bored", "无聊了十五分钟", "無聊了十五分鐘", "Quince minutos de aburrimiento", "Quinze minuts d'avorriment"],
 ["Be bored. Fifteen minutes. Sit. No phone, no book, no TV. Bored is where ideas come from, you know. Ask Josep's clock.", "闷一会儿。十五分钟。坐下。不看手机，不看书，不看电视。闷，是想法的老家。问 Josep 的钟。", "悶十五分鐘。坐定定，唔睇電話、唔睇書、唔睇電視。啲好主意都係悶出嚟㗎。唔信問下 Josep 個鐘。", "Abúrrete. Quince minutos. Siéntate. Sin móvil, sin libro, sin tele. Aburrido es de donde vienen ideas. Pregunta al reloj de Josep.", "Avorreix-te quinze minuts. Seu. Sense mòbil, sense llibre, sense tele. Les idees neixen de l'avorriment. Pregunta-ho al rellotge d'en Josep."],
 ["mei", ["I got bored for fifteen minutes and accidentally learnt to braid. Character development.", "我无聊了十五分钟，意外学会了编辫子。成长线。", "我無聊了十五分鐘，意外學會了編辮子。角色成長。", "Me aburrí quince minutos y aprendí a hacer trenzas sin querer. Desarrollo de personaje.", "Em vaig avorrir quinze minuts i, sense voler, vaig aprendre a fer trenes. Evolució del personatge."]]);
X("d25", 3, "", ["Chose one small habit for a week", "选了一个小习惯坚持一周", "選了一個小習慣堅持一週", "Elegí un hábito pequeño para una semana", "Vaig triar un hàbit petit per a una setmana"],
 ["Pick one thing from my jar. Do it seven days. I don't count, you don't count. Just do lah. After, it's yours.", "从我的罐子挑一样。做七天。我不数，你也不数。做就是了。然后，它就是你的咯。", "喺我個樽度揀一樣，做七日。我唔數，你都唔好數，做就得。做完，佢就係你嘅喇。", "Elige una cosa de mi tarro. Hazla siete días. Yo no cuento, tú no cuentas. Solo haz. Después, es tuya.", "Tria una cosa del meu pot i fes-la set dies. Jo no compto, i tu tampoc. Fes-la i prou. Després, ja és teva."],
 ["cats", ["*Miso and Yuzu demonstrate a habit: sitting in the same sunny spot every day at four*", "*味噌和柚子示范了一个习惯：每天四点坐在同一块太阳底下*", "*味噌和柚子示範了一個習慣：每天四點坐在同一塊太陽底下*", "*Miso y Yuzu enseñan un hábito: sentarse cada día a las cuatro en el mismo rayo de sol*", "*Miso i Yuzu fan una demostració d'hàbit: seure cada dia a les quatre al mateix raig de sol*"]]);
})();
